#pragma once

#include <QByteArray>
#include <QIcon>
#include <QPixmap>

// =====================================================================
// AppTheme -- paleta oficial da Prefeitura de Piranga e marca embarcada.
// Gerado a partir da logo oficial (logo_piranga.png), sem depender de
// arquivos .qrc/CMake: a imagem fica embutida como Base64 no binario.
// Camada puramente visual -- nao contem regra de negocio.
// =====================================================================
namespace AppTheme
{
    // Paleta extraida diretamente da logo oficial
    inline constexpr const char *Verde        = "#009331";
    inline constexpr const char *VerdeEscuro  = "#00722A";
    inline constexpr const char *VerdeClaro   = "#E7F6EC";
    inline constexpr const char *Azul         = "#004082";
    inline constexpr const char *AzulEscuro   = "#00305F";
    inline constexpr const char *AzulClaro    = "#E9F1FB";
    inline constexpr const char *Tinta        = "#0B2545";
    inline constexpr const char *TextoSuave   = "#5A6B7A";
    inline constexpr const char *FundoPagina  = "#F1F5F9";
    inline constexpr const char *Cartao       = "#FFFFFF";
    inline constexpr const char *Borda        = "#DCE4EC";
    inline constexpr const char *Perigo       = "#C0392B";
    inline constexpr const char *PerigoEscuro = "#8E2A20";

    namespace Detalhe
    {
        inline const QByteArray &logoBase64()
        {
            static const QByteArray dados =
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            ""
            "";
            return dados;
        }
    }

    // Logo oficial da Prefeitura de Piranga em resolucao original.
    inline QPixmap logoPixmap()
    {
        QPixmap mapa;
        mapa.loadFromData(QByteArray::fromBase64(Detalhe::logoBase64()), "PNG");
        return mapa;
    }

    // Versao redimensionada com suavizacao, pronta para uso em QLabel/QIcon.
    inline QPixmap logoPixmap(int alturaAlvo)
    {
        const QPixmap original = logoPixmap();
        return original.scaledToHeight(alturaAlvo, Qt::SmoothTransformation);
    }

    inline QIcon appIcon()
    {
        return QIcon(logoPixmap());
    }
}